from itertools import permutations

def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for string in lst:
        if set(string) != {'(', ')'}:
            return 'No'

    perms = permutations(lst)
    for perm in perms:
        concat_str = ''.join(perm)
        if is_balanced(concat_str):
            return 'Yes'

    return 'No'

