def do_algebra(operator, operand):
    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '//':
            return 2
        if op == '**':
            return 3
        return 0

    def apply_operation(operands, operators):
        while len(operators) > 0 and precedence(operators[-1]) >= precedence('*'):
            op = operators.pop()
            right = operands.pop()
            left = operands.pop()
            if op == '+':
                operands.append(left + right)
            elif op == '-':
                operands.append(left - right)
            elif op == '*':
                operands.append(left * right)
            elif op == '//':
                operands.append(left // right)
            elif op == '**':
                operands.append(left ** right)
        return operands, operators

    operands = []
    operators = []

    for i in range(len(operand)):
        operands.append(operand[i])
        if i < len(operator):
            while len(operators) > 0 and precedence(operators[-1]) >= precedence(operator[i]):
                operands, operators = apply_operation(operands, operators)
            operators.append(operator[i])

    while len(operators) > 0:
        operands, operators = apply_operation(operands, operators)

    return operands[0]

